create table public.crane_monthly_templates (
 id uuid primary key default gen_random_uuid(), country_code text not null check(country_code in ('TW','VM','MX')),
 equipment_id uuid not null references public.equipments(id), department_id uuid not null references public.departments(id),
 items jsonb not null, revision integer not null default 1, updated_by uuid not null references public.operator_accounts(id),
 updated_at timestamptz not null default now(), unique(country_code,equipment_id)
);
create index crane_monthly_templates_department_idx on public.crane_monthly_templates(department_id);
alter table public.crane_monthly_templates enable row level security;
revoke all on public.crane_monthly_templates from public,anon,authenticated;
grant all on public.crane_monthly_templates to service_role;
alter table public.crane_inspection_records add column template_snapshot jsonb, add column template_revision integer not null default 0;
create function public.crane_monthly_default_items() returns jsonb language sql immutable security invoker set search_path=public,pg_temp as $default$ select '[{"id":1,"name":{"zh":"過捲預防裝置","en":"Overwind Prevention Device","es":"Dispositivo de prevención de  retorcer","vi":"Thiết bị chống cuốn quá mức"},"standard":{"zh":"具有自動遮斷動力及制動之機能，作動安全距離符合規定","en":"It has the function of automatically shutting off power and braking, and the operating safety distance complies with regulations.","es":"Corta automáticamente la energía y frena; la distancia de seguridad de actuación cumple los requisitos.","vi":"Tự động ngắt nguồn và phanh; khoảng cách an toàn khi tác động đáp ứng quy định."}},{"id":2,"name":{"zh":"過負荷預防裝置","en":"Overload Prevention Device","es":"Dispositivo de prevención de sobrecarga","vi":"Thiết bị chống quá tải"},"standard":{"zh":"當過負荷時具有自動遮斷動力機能","en":"Automatically cut off power when overloaded","es":"Corta automáticamente la energía cuando hay sobrecarga.","vi":"Tự động ngắt nguồn khi quá tải."}},{"id":3,"name":{"zh":"防止逸走裝置","en":"Anti-Derailing Device","es":"Dispositivo antideslizamiento","vi":"Thiết bị chống trôi"},"standard":{"zh":"無損傷、變形，應具有將機具確實固定之機能","en":"No damage or deformation, and should be able to firmly fix the machine","es":"Sin daños ni deformaciones; fija firmemente la máquina.","vi":"Không hư hỏng hoặc biến dạng; có khả năng cố định chắc chắn thiết bị."}},{"id":4,"name":{"zh":"阻擋器、緩衝裝置","en":"Stopper and Buffer Device","es":"Dispositivo de tope y amortiguador","vi":"Bộ chặn và bộ giảm chấn"},"standard":{"zh":"無損傷、歪斜、脫落，機能正常","en":"No damage, skewness, or falling off, and functions normally","es":"Sin daños, inclinación ni desprendimiento; funcionamiento normal.","vi":"Không hư hỏng, lệch hoặc rơi ra; hoạt động bình thường."}},{"id":5,"name":{"zh":"制動器","en":"Brake","es":"Freno","vi":"Phanh"},"standard":{"zh":"剎車動作狀況圓滑","en":"Braking action is smooth","es":"El frenado es suave.","vi":"Phanh hoạt động êm."}},{"id":6,"name":{"zh":"制動器","en":"Brake","es":"Freno","vi":"Phanh"},"standard":{"zh":"無顯著磨損、剝離、油污","en":"No significant wear, peeling, or oil stains","es":"Sin desgaste significativo, desprendimientos ni manchas de aceite.","vi":"Không mài mòn đáng kể, bong tróc hoặc dính dầu."}},{"id":7,"name":{"zh":"鋼索","en":"Wire Rope","es":"Cable de acero","vi":"Cáp thép"},"standard":{"zh":"直徑磨損未超過公稱直徑之7％","en":"The diameter wear does not exceed 7% of the nominal diameter","es":"La reducción del diámetro por desgaste no supera el 7 % del diámetro nominal.","vi":"Đường kính bị mòn không vượt quá 7% đường kính danh nghĩa."}},{"id":8,"name":{"zh":"鋼索","en":"Wire Rope","es":"Cable de acero","vi":"Cáp thép"},"standard":{"zh":"一撚間素線斷裂未超過10％","en":"The line breaks not more than 10%.","es":"Los alambres rotos en un paso de cable no superan el 10 %.","vi":"Số sợi đứt trong một bước bện không vượt quá 10%."}},{"id":9,"name":{"zh":"鋼索","en":"Wire Rope","es":"Cable de acero","vi":"Cáp thép"},"standard":{"zh":"無扭結、顯著變形、腐蝕","en":"No kinks, significant deformation, corrosion","es":"Sin cocas, deformación significativa ni corrosión.","vi":"Không xoắn gập, biến dạng đáng kể hoặc ăn mòn."}},{"id":10,"name":{"zh":"鋼索","en":"Wire Rope","es":"Cable de acero","vi":"Cáp thép"},"standard":{"zh":"尾端固定正確具防鬆或自緊性能","en":"The tail end is fixed correctly with anti-loosening or self-tightening performance","es":"El extremo está fijado correctamente con función antiaflojamiento o autobloqueo.","vi":"Đầu cáp được cố định đúng, có khả năng chống lỏng hoặc tự siết."}},{"id":11,"name":{"zh":"吊鏈","en":"Hoist Chain","es":"Cadena de elevación","vi":"Xích nâng"},"standard":{"zh":"斷面直徑減少未超過10％","en":"The cross-sectional diameter does not decrease by more than 10%","es":"La reducción del diámetro de la sección no supera el 10 %.","vi":"Đường kính tiết diện giảm không quá 10%."}},{"id":12,"name":{"zh":"吊鏈","en":"Hoist Chain","es":"Cadena de elevación","vi":"Xích nâng"},"standard":{"zh":"伸長率未超過5％","en":"Elongation does not exceed 5%","es":"El alargamiento no supera el 5 %.","vi":"Độ giãn dài không vượt quá 5%."}},{"id":13,"name":{"zh":"吊鏈","en":"Hoist Chain","es":"Cadena de elevación","vi":"Xích nâng"},"standard":{"zh":"無龜裂、腐蝕","en":"No cracking or corrosion","es":"Sin grietas ni corrosión.","vi":"Không nứt hoặc ăn mòn."}},{"id":14,"name":{"zh":"吊鉤","en":"Hook","es":"Gancho","vi":"Móc cẩu"},"standard":{"zh":"吊鉤應鍛造成形，能自由圓滑轉動，並不得龜裂或明顯之銹蝕等有之缺陷，且未焊補、電鍍等改造。","en":"The hook should be forged and able to rotate smoothly and freely, and should not have defects such as cracks or obvious rust, and should not be modified by welding, electroplating, etc.","es":"El gancho está forjado, gira libre y suavemente, no tiene grietas ni corrosión evidente y no ha sido modificado mediante soldadura, galvanizado u otros procesos.","vi":"Móc phải được rèn, quay tự do và êm, không nứt hoặc gỉ rõ rệt; không được sửa đổi bằng hàn đắp, mạ điện hoặc phương pháp tương tự."}},{"id":15,"name":{"zh":"吊鉤","en":"Hook","es":"Gancho","vi":"Móc cẩu"},"standard":{"zh":"吊鉤槽輪組之鍵板、鎖緊銷、止動螺栓、開口銷等無脫落、鬆動或損傷影響安全動作。","en":"The key plate, locking pin, stop bolt, cotter pin, etc. of the hook sheave assembly must not fall off, become loose or be damaged, which may affect safe operation.","es":"Las placas de chaveta, pasadores de bloqueo, pernos de tope y pasadores hendidos del conjunto de poleas del gancho no están sueltos, desprendidos ni dañados de forma que afecten la seguridad.","vi":"Tấm chặn, chốt khóa, bu lông chặn, chốt chẻ của cụm puly móc không bị rơi, lỏng hoặc hư hỏng ảnh hưởng đến vận hành an toàn."}},{"id":16,"name":{"zh":"吊鉤","en":"Hook","es":"Gancho","vi":"Móc cẩu"},"standard":{"zh":"吊鉤開口寬度未超過原標示尺寸5%。與吊具接觸部分磨損量無超過製造廠之規定值者。(無規定值時，其磨損量不得超過原尺寸之5%)(單位:mm)","en":"The width of the hook opening does not exceed the original marked size by 5%. The wear of the part in contact with the sling does not exceed the value specified by the manufacturer. (If there is no specified value, the wear shall not exceed 5% of the original size)","es":"La abertura del gancho no excede en un 5 % la medida original. El desgaste en contacto con el aparejo no supera el límite del fabricante; si no se especifica, no supera el 5 % de la medida original (mm).","vi":"Độ mở móc không vượt quá kích thước ban đầu 5%. Độ mòn tại phần tiếp xúc với phụ kiện nâng không vượt quá giới hạn của nhà sản xuất; nếu không có giới hạn, không vượt quá 5% kích thước ban đầu (mm)."}},{"id":17,"name":{"zh":"吊鉤","en":"Hook","es":"Gancho","vi":"Móc cẩu"},"standard":{"zh":"吊鉤應設有防止吊掛用鋼索等自該吊鉤脫落之裝置且作用良好。","en":"The hook should be equipped with a device to prevent the hanging wire rope etc. from falling off the hook and the device should function well.","es":"El gancho tiene un dispositivo que impide que el cable de suspensión se desprenda y este funciona correctamente.","vi":"Móc có thiết bị ngăn cáp treo tuột khỏi móc và thiết bị hoạt động tốt."}},{"id":18,"name":{"zh":"吊具","en":"Lifting Gear","es":"Equipo de elevación","vi":"Phụ kiện nâng"},"standard":{"zh":"無顯著之變形、裂痕。","en":"No significant deformation or cracks.","es":"Sin deformación significativa ni grietas.","vi":"Không biến dạng đáng kể hoặc nứt."}},{"id":19,"name":{"zh":"供電線、配線","en":"Power Cable and Wiring","es":"Cable de alimentación y cableado","vi":"Dây nguồn và hệ thống dây điện"},"standard":{"zh":"絕緣被覆無損傷或老化、無過度張開、扭結、固定夾鬆弛現象","en":"The insulation coating is not damaged or aged, and there is no excessive opening, kinking, or loosening of the fixing clips.","es":"El aislamiento no está dañado ni envejecido; sin separación excesiva, cocas ni abrazaderas flojas.","vi":"Lớp cách điện không hư hỏng hoặc lão hóa; không bị mở quá mức, xoắn gập hoặc lỏng kẹp cố định."}},{"id":20,"name":{"zh":"集電裝置","en":"Power Collector Device","es":"Dispositivo colector de energía","vi":"Bộ thu điện"},"standard":{"zh":"應能正常給電，無接觸不良、絕緣物損傷之現象","en":"It should be able to supply power normally without any poor contact or insulation damage.","es":"Suministra energía normalmente, sin mal contacto ni daños en el aislamiento.","vi":"Cấp điện bình thường, không tiếp xúc kém hoặc hư hỏng cách điện."}},{"id":21,"name":{"zh":"配電盤","en":"Distribution Panel","es":"Panel de distribución","vi":"Tủ điện"},"standard":{"zh":"檢查配線接頭確實接牢、遮斷器之開關、閘刀開關、電磁接觸器等機能無異常","en":"Check that the wiring connectors are firmly connected, and that there are no abnormalities in the functions of the circuit breaker, knife switch, electromagnetic contactor, etc.","es":"Las conexiones están firmes; los interruptores automáticos, seccionadores de cuchilla y contactores electromagnéticos funcionan sin anomalías.","vi":"Các đầu nối dây chắc chắn; bộ ngắt mạch, cầu dao và công tắc tơ điện từ hoạt động không bất thường."}},{"id":22,"name":{"zh":"操作開關","en":"Control Switch","es":"Interruptor de control","vi":"Công tắc điều khiển"},"standard":{"zh":"操作開關或控制器作動狀況正常，作動方向正確","en":"The operating switch or controller is operating normally and the operating direction is correct.","es":"Los interruptores o controladores funcionan normalmente y en la dirección correcta.","vi":"Công tắc hoặc bộ điều khiển hoạt động bình thường, hướng hoạt động chính xác."}}]'::jsonb $default$;
update public.crane_inspection_records set template_snapshot=public.crane_monthly_default_items() where kind='monthly';

create function public.save_crane_monthly_template(p_country text,p_account uuid,p_equipment uuid,p_revision integer,p_items jsonb)
returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare u record; e record; old public.crane_monthly_templates; saved public.crane_monthly_templates; x jsonb; v jsonb; lang text; field text; photo uuid; i integer:=0;
begin
 select role,department_id,is_active into u from operator_accounts where id=p_account;
 if not found or not u.is_active or u.role not in ('admin','supervisor') then raise exception 'forbidden';end if;
 select eq.*,g.name_zh as group_name into e from equipments eq left join equipment_groups g on g.id=eq.equipment_group_id where eq.id=p_equipment and eq.country_code=p_country and eq.archived_at is null for share of eq;
 if not found or (u.role<>'admin' and u.department_id is distinct from e.department_id) then raise exception 'forbidden';end if;
 if length(btrim(coalesce(e.machine_no,'')))=0 or (e.name_zh||' '||coalesce(e.group_name,''))!~'天車|起重機' then raise exception 'invalid_crane';end if;
 perform pg_advisory_xact_lock(hashtextextended('crane-template:'||p_country||':'||p_equipment,0));
 select * into old from crane_monthly_templates where country_code=p_country and equipment_id=p_equipment for update;
 if p_revision is distinct from coalesce(old.revision,0) then raise exception 'record_changed';end if;
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 200 or length(p_items::text)>1000000 then raise exception 'invalid_template';end if;
 for x in select * from jsonb_array_elements(p_items) loop
  i:=i+1;
  if x->>'id' is distinct from i::text or x-array['id','name','standard','reference_photo_id']<>'{}'::jsonb then raise exception 'invalid_template';end if;
  foreach field in array array['name','standard'] loop
   v:=x->field;if jsonb_typeof(v) is distinct from 'object' or length(trim(coalesce(v->>'zh',''))) not between 1 and 3000 or v-array['zh','en','es','vi']<>'{}'::jsonb then raise exception 'invalid_template';end if;
   foreach lang in array array['zh','en','es','vi'] loop
    if v?lang and (jsonb_typeof(v->lang) is distinct from 'string' or length(v->>lang)>3000) then raise exception 'invalid_template';end if;
   end loop;
  end loop;
  if coalesce(x->>'reference_photo_id','')<>'' then
   photo:=(x->>'reference_photo_id')::uuid;
   if not exists(select 1 from inspection_reference_photos p where p.id=photo and p.country_code=p_country and (u.role='admin' or p.uploaded_by=p_account or exists(select 1 from jsonb_array_elements(coalesce(old.items,'[]')) it where it->>'reference_photo_id'=photo::text))) then raise exception 'invalid_photo';end if;
  end if;
 end loop;
 insert into crane_monthly_templates(country_code,equipment_id,department_id,items,revision,updated_by)
 values(p_country,p_equipment,e.department_id,p_items,coalesce(old.revision,0)+1,p_account)
 on conflict(country_code,equipment_id) do update set items=excluded.items,revision=excluded.revision,department_id=excluded.department_id,updated_by=p_account,updated_at=now() returning * into saved;
 insert into audit_logs(account_id,action,entity_type,entity_id,country_code,payload) values(p_account,'crane_template_save','crane_monthly_template',saved.id,p_country,jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(saved)));
 return to_jsonb(saved);
end $$;
CREATE OR REPLACE FUNCTION public.save_crane_record_v2(p_country text, p_account uuid, p_equipment uuid, p_kind text, p_date date, p_revision integer, p_results jsonb, p_details jsonb, p_inspector text, p_leader text, p_supervisor text, p_completed boolean, p_confirm boolean, p_template_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u record; eq record; prior public.crane_inspection_records; saved public.crane_inspection_records; period date; i integer; v jsonb; expected integer; snapshot jsonb; template public.crane_monthly_templates; snapshot_revision integer:=0;
begin
 select role,department_id,is_active into u from operator_accounts where id=p_account;
 if not found or not u.is_active or u.role not in ('admin','supervisor','operator') then raise exception 'forbidden'; end if;
 select e.*,g.name_zh as group_name into eq from equipments e left join equipment_groups g on g.id=e.equipment_group_id where e.id=p_equipment and e.country_code=p_country and e.archived_at is null for share of e;
 if not found or (u.role<>'admin' and u.department_id is distinct from eq.department_id) then raise exception 'forbidden'; end if;
 if not exists(select 1 from departments where id=eq.department_id and country_code=p_country and is_active) or length(btrim(eq.machine_no))=0 or (eq.name_zh||' '||coalesce(eq.group_name,'')) !~ '(天車|起重機)' then raise exception 'invalid_crane'; end if;
 if p_kind is null or p_kind not in ('monthly','daily') or p_date is null or p_date<date '2000-01-01' or p_date>(now() at time zone 'Asia/Taipei')::date or p_revision is null or p_revision<0 or jsonb_typeof(p_results) is distinct from 'array' or jsonb_typeof(p_details) is distinct from 'object' or length(p_details::text)>25000 or p_inspector is null or length(btrim(p_inspector)) not between 1 and 100 or p_leader is null or length(p_leader)>100 or p_supervisor is null or length(p_supervisor)>100 or p_completed is null or p_confirm is null then raise exception 'invalid_crane_record'; end if;
 if u.role='operator' and (p_confirm or p_supervisor<>'' or p_leader<>'') then raise exception 'forbidden'; end if;
 if p_details - array['model','capacity','location','hazard','risk','measures','suitability'] <> '{}'::jsonb then raise exception 'invalid_crane_record'; end if;
 for v in select value from jsonb_each(p_details) loop
  if jsonb_typeof(v) is distinct from 'string' or length(v#>>'{}')>3000 then raise exception 'invalid_crane_record'; end if;
 end loop;
 if p_confirm and (not p_completed or length(btrim(p_supervisor))=0) then raise exception 'confirmation_incomplete'; end if;
 perform pg_advisory_xact_lock(hashtextextended('crane-template:'||p_country||':'||p_equipment,0));
 period:=case when p_kind='monthly' then date_trunc('month',p_date)::date else p_date end;
 perform pg_advisory_xact_lock(hashtextextended('crane:'||p_country||':'||p_equipment||':'||p_kind||':'||period,0));
 select * into prior from crane_inspection_records where country_code=p_country and equipment_id=p_equipment and kind=p_kind and period_date=period for update;
 if coalesce(prior.revision,0)<>p_revision then raise exception 'record_changed'; end if;
 if prior.id is not null and prior.department_id<>eq.department_id then raise exception 'equipment_changed'; end if;
 if p_kind='monthly' then
  select * into template from crane_monthly_templates where country_code=p_country and equipment_id=p_equipment;
  snapshot:=coalesce(prior.template_snapshot,template.items,crane_monthly_default_items());
  snapshot_revision:=case when prior.id is not null then prior.template_revision else coalesce(template.revision,0) end;
  if p_template_revision is distinct from snapshot_revision then raise exception 'template_changed';end if;
  expected:=jsonb_array_length(snapshot);
 else expected:=6;end if;
 if jsonb_array_length(p_results)<>expected then raise exception 'invalid_crane_record';end if;
 for i in 0..expected-1 loop
  v:=p_results->i;
  if v->>'id' is distinct from (i+1)::text or jsonb_typeof(v->'value') is distinct from 'string' or (p_kind='monthly' and v->>'value' not in ('','X','Δ','✔','─')) or (p_kind='daily' and v->>'value' not in ('','ˇ','×')) then raise exception 'invalid_crane_record'; end if;
  if p_completed and v->>'value'='' then raise exception 'confirmation_incomplete'; end if;
 end loop;
 insert into crane_inspection_records(country_code,department_id,equipment_id,kind,period_date,inspection_date,equipment_snapshot,results,details,inspector_name,leader_name,supervisor_name,completed,confirmed_at,revision,updated_by,template_snapshot,template_revision)
 values(p_country,eq.department_id,p_equipment,p_kind,period,p_date,coalesce(prior.equipment_snapshot,jsonb_build_object('machine_no',eq.machine_no,'property_no',eq.property_no,'name_zh',eq.name_zh)),p_results,p_details,btrim(p_inspector),btrim(p_leader),case when p_confirm then btrim(p_supervisor) else '' end,p_completed,case when p_confirm then now() end,coalesce(prior.revision,0)+1,p_account,snapshot,snapshot_revision)
 on conflict(country_code,equipment_id,kind,period_date) do update set inspection_date=excluded.inspection_date,results=excluded.results,details=excluded.details,inspector_name=excluded.inspector_name,leader_name=excluded.leader_name,supervisor_name=excluded.supervisor_name,completed=excluded.completed,confirmed_at=excluded.confirmed_at,revision=excluded.revision,updated_by=p_account,updated_at=now() returning * into saved;
 insert into audit_logs(account_id,action,entity_type,entity_id,payload,country_code) values(p_account,'crane_record_save','crane_inspection_record',saved.id,jsonb_build_object('before',to_jsonb(prior),'after',to_jsonb(saved)),p_country);
 return to_jsonb(saved);
end $function$
;
create or replace function public.save_crane_record(p_country text,p_account uuid,p_equipment uuid,p_kind text,p_date date,p_revision integer,p_results jsonb,p_details jsonb,p_inspector text,p_leader text,p_supervisor text,p_completed boolean,p_confirm boolean)
returns jsonb language sql security invoker set search_path=public,pg_temp as $$ select public.save_crane_record_v2(p_country,p_account,p_equipment,p_kind,p_date,p_revision,p_results,p_details,p_inspector,p_leader,p_supervisor,p_completed,p_confirm,0) $$;
revoke all on function public.crane_monthly_default_items(),public.save_crane_monthly_template(text,uuid,uuid,integer,jsonb),public.save_crane_record_v2(text,uuid,uuid,text,date,integer,jsonb,jsonb,text,text,text,boolean,boolean,integer) from public,anon,authenticated;
grant execute on function public.crane_monthly_default_items(),public.save_crane_monthly_template(text,uuid,uuid,integer,jsonb),public.save_crane_record_v2(text,uuid,uuid,text,date,integer,jsonb,jsonb,text,text,text,boolean,boolean,integer) to service_role;
